#pragma once
#include <atomic>
#include <condition_variable>
#include <cstddef>
#include <functional>
#include <mutex>
#include <queue>
#include <thread>
#include <utility>
#include <vector>
class TaskQueue{
 std::mutex mutex_;
 std::condition_variable ready_;
 std::queue<std::function<void()>> tasks_;
 std::vector<std::thread> workers_;
 bool accepting_{true};
 void work(){for(;;){std::function<void()> task;{std::unique_lock lock(mutex_);ready_.wait(lock,[&]{return !accepting_||!tasks_.empty();});if(tasks_.empty())return;task=std::move(tasks_.front());tasks_.pop();}task();}}
public:
 explicit TaskQueue(std::size_t count){for(std::size_t index=0;index<count;++index)workers_.emplace_back([this]{work();});}
 TaskQueue(const TaskQueue&)=delete;
 TaskQueue& operator=(const TaskQueue&)=delete;
 bool submit(std::function<void()> task){{std::lock_guard lock(mutex_);if(!accepting_)return false;tasks_.push(std::move(task));}ready_.notify_one();return true;}
 void close(){ {std::lock_guard lock(mutex_);accepting_=false;}ready_.notify_all();for(auto& worker:workers_)if(worker.joinable())worker.join();workers_.clear();}
 std::size_t worker_count()const{return workers_.size();}
 ~TaskQueue(){close();}
};
struct TaskQueueResult{long long sum;std::size_t workers;bool rejectedAfterClose;};
inline TaskQueueResult run_tasks(const std::vector<int>& tasks){constexpr std::size_t workerCount=4;TaskQueue queue(workerCount);std::atomic<long long> sum{0};for(int value:tasks)queue.submit([&sum,value]{sum.fetch_add(value,std::memory_order_relaxed);});queue.close();const bool rejected=!queue.submit([]{});return{sum.load(std::memory_order_relaxed),workerCount,rejected};}

